const search = (xs, target) => {
  let lo = 0,
    hi = xs.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (xs[mid] === target) return mid;
    xs[mid] < target ? (lo = mid + 1) : (hi = mid - 1);
  }
  return -1;
};
